export const bankedClozeDirections='Fill in the blanks by selecting suitable words from the word bank. Write down the capital letter A-O in each blank. You may not use any of the words more than once.';
export const bankedClozeWords=['attribute','blame','casual','concrete','consultants','familiarity','dynamic','graphs','distinctive','obtain','qualitative','quantitative','stability','subjective','thrive'];
export const bankedClozeAnswers=['E','J','L','F','K','N','B','D','G','M'];
export const bankedClozeWordAnswers=bankedClozeAnswers.map(label=>bankedClozeWords[label.charCodeAt(0)-65]);
export function bankedClozeHTML({sharedDirections=true,captions=false,tableBank=false}={}){
  const blank=index=>`<span class="comp-abs-input"><input id="cloze-${index}" type="text"><span class="input-value-measure"></span></span>`;
  // The first eight blanks reproduce the supplied screenshot. The final two
  // sentences are synthetic to exercise scrolling and all ten answer fields.
  const paragraphs=[
    `When a business decides to expand into other countries, one factor they need to consider is the culture of the country, especially in terms of how it affects working practices. To do this, many companies hire 1) ${blank(0)} who offer advice to businesses about how to operate in new markets.`,
    `The first thing they do is collect as much data as they can about the company's corporate culture, and the culture of the new markets. The more data they can 2) ${blank(1)}, the easier it will be to help the company achieve its goals. Obviously, the easiest is 3) ${blank(2)} data such as the number of employees per manager, the average age of the workforce, or different types of competitors in the market. But to really gain 4) ${blank(3)} with a new market, it's also essential to collect 5) ${blank(4)} data, especially from the target customers of that country. Of course, sometimes this kind of data can be quite 6) ${blank(5)} and requires interpretation or explanation. For example, one consultant, Maya Hennings, says, "I once had a Japanese company that wanted to open a new factory in Spain. They couldn't understand why their hierarchical structure was unlikely to work. I certainly don't 7) ${blank(6)} them, because sometimes the information I give companies can seem rather odd. I even tried to give them some 8) ${blank(7)} examples of how other companies operated in Spain, but they still found it difficult to grasp."`,
    `A successful workplace can be 9) ${blank(8)} while maintaining long-term 10) ${blank(9)}.`
  ];
  const direction=`<div class="layout-direction-container"><div class="abs-direction"><strong>Directions: </strong>${bankedClozeDirections}</div></div>`;
  const exercise=`<div class="question-common-abs-scoop"><div class="item">${paragraphs.map(p=>'<p>'+p+'</p>').join('')}</div></div>`;
  const bank=tableBank?'<table>'+Array.from({length:5},(_,row)=>'<tr>'+bankedClozeWords.slice(row*3,row*3+3).map((word,i)=>'<td>'+String.fromCharCode(65+row*3+i)+'. '+word+'</td>').join('')+'</tr>').join('')+'</table>':`<div class="option-wrapper">${bankedClozeWords.map((word,i)=>`<div class="option"${captions?` data-option-value="${word}"`:''}>${captions?`<span class="caption">${String.fromCharCode(65+i)}</span><span>${word}</span>`:String.fromCharCode(65+i)+'. '+word}</div>`).join('')}</div>`;
  const body=tableBank?`<div class="layout-material-container">${bank}</div><div class="layoutBody-container"><div class="layout-reply-container">${exercise}</div></div>`:`<div class="layoutBody-container">${bank}<div class="layout-material-container">${exercise}</div></div>`;
  return `<!doctype html><html><head><meta charset="utf-8"><style>body{font:16px Arial;margin:20px}.option-wrapper{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.option{padding:8px;border:1px solid #ddd}.layoutBody-container{display:grid;grid-template-columns:1fr 1fr;gap:30px}.layout-material-container{max-height:320px;overflow:auto;line-height:2}.input-value-measure{position:absolute;left:-10000px}input{width:100px}.abs-direction{margin-bottom:20px}</style></head><body>
    <header><div class="pc-break-crumb"><span class="pc-break-crumb-text">Offline English</span><span class="pc-break-crumb-text">Unit 7</span><span class="pc-break-crumb-text">Text A</span></div><div class="pc-header-tab-activity">Language in focus</div><div class="pc-task pc-header-task-activity">Banked cloze</div></header>
    <main class="pc-main-container">${sharedDirections?direction:''}<div class="layout-container">${sharedDirections?'':direction}${body}</div></main>
    <footer><button id="submit">提交</button></footer><script>window.submissions=[];window.inputWrites=0;document.querySelectorAll('input').forEach(input=>input.oninput=()=>{window.inputWrites++;input.nextElementSibling.textContent=input.value;});document.querySelector('#submit').onclick=()=>{const values=[...document.querySelectorAll('input')].map(el=>el.value);window.submissions.push(values);if(JSON.stringify(values)!==${JSON.stringify(JSON.stringify(bankedClozeAnswers))})return;document.querySelector('main').innerHTML='<h2>答题小结</h2><p>共10道题，客观题10道，主观题0道</p><p>正确 (10/10)</p><p>错误 (0/10)</p><p>未作答 0</p>';document.querySelector('footer').innerHTML='';};</script></body></html>`;
}
